-- EasyCast interface and control help; game names remain client data.
EasyCast.localeTexts.frFR={
    ["Kopieren von"]="Copier depuis",
    ["Ersetzt die gesamte Belegung: %s · %s. Auch leere Einträge werden übernommen."]="Remplace toutes les affectations : %s · %s. Les entrées vides sont aussi copiées.",
    ["Quelle und Ziel sind gleich; nichts geändert."]="Source et destination identiques ; aucune modification.",
    ["Belegung kopiert: %s → %s (%s)."]="Affectations copiées : %s → %s (%s).",
    ["Kopiert alle Maus-, Mausrad- und Tastaturbelegungen der Quelle in die oben gewählte Zusatztaste. Ersetzt auch leere Einträge. Freundlich und Feindlich bleiben getrennt."]="Copie toutes les affectations de souris, molette et clavier de la source vers le modificateur choisi en haut. Les entrées vides remplacent aussi les affectations existantes. Amical et hostile restent séparés.",
    ["Quell-Zusatztaste wählen. Kopiert wird erst mit Kopieren von. Auch gespeicherte Belegungen reservierter Tasten sind als Quelle verfügbar."]="Choisissez le modificateur source. La copie démarre uniquement avec Copier depuis. Les affectations enregistrées des modificateurs réservés peuvent aussi servir de source.",

    ["  ·  /ec  ·  Enter oder Feld verlassen speichert"]="  ·  /ec  ·  Entrée ou quitter le champ enregistre",
    [" (Aussetztaste)|r"]=" (touche de pause)|r",
    [" (Selbstzaubertaste)|r"]=" (sort sur soi)|r",
    [" (bereits reserviert)|r"]=" (déjà réservée)|r",
    [" Einträge pro Zeile"]=" entrées par ligne",
    [" erkannt · Taste loslassen zum Übernehmen."]=" détectée · relâchez pour valider.",
